done.script:
var fd = tree.root.get_node_or_null("/root/Main/FormationsDialog")
if fd == null:
	return false
var q = [fd]
while not q.is_empty():
	var nd = q.pop_back()
	if nd is OptionButton and nd.item_count > 0 and nd.get_item_text(0) == "(Unattached)":
		return nd.selected == 1
	for c in nd.get_children():
		q.append(c)
return false

var fd = tree.root.get_node_or_null("/root/Main/FormationsDialog")
if fd == null:
	return false
var q = [fd]
while not q.is_empty():
	var nd = q.pop_back()
	if nd is CheckBox and str(nd.text).begins_with("Boyz") and not ("Reserves" in str(nd.text)):
		return nd.button_pressed
	for c in nd.get_children():
		q.append(c)
return false

var dc = main.get("deployment_controller") if main != null else null
if dc == null or str(dc.unit_id) != "U_BATTLEWAGON_T":
	return false
var wagon = GameState.get_unit("U_BATTLEWAGON_T")
var base_face = BoardState.get_default_facing_for_player(int(wagon.get("owner", 1)))
var rot = null
if dc.temp_positions.size() > 0 and dc.temp_positions[0] != null and dc.temp_rotations.size() > 0:
	rot = float(dc.temp_rotations[0])
elif dc.ghost_sprite != null and dc.ghost_sprite.has_method("get_base_rotation"):
	rot = dc.ghost_sprite.get_base_rotation()
if rot == null:
	return false
return abs(wrapf(float(rot) - base_face, -PI, PI)) > 0.5
